package com.qiban.companion;
import java.util.*;
import java.util.regex.*;

/** Port of the Foundation parser. Display prose is never rewritten to manufacture speech. */
final class SpokenDialogue {
    static final String INSTRUCTION="reply 可保留动作、外貌、心理活动；另给 speech_zh 字符串，只写角色实际说出口的中文台词。纯动作／纯心理填空字符串。speech_ja 只翻译实际台词，不新增对白。";
    private static final String[] MENTAL={"心想","心里想","心中想","心里说","内心","心理","暗想","默想","腹诽","thought to herself","thought to himself","thinking to herself","thinking to himself"};
    private static final String[] STAGES={"微微","轻轻","缓缓","轻声","柔声","低声","脸颊","眼睛","眼神","眼眸","肩膀","指尖","双唇","唇角","嘴角","抬手","抬起","低头","转身","转过","垂下","偏过","侧过","看着","望着","笑着","笑了","说道","说着","回答道","问道","心想","心里","内心","默默","呼吸","脸红","害羞地","smile","blush","whisper","looks at","turns","nods"};
    private static final String[] TAGS={"台词：","台词:","对白：","对白:","对话：","对话:","说：","说:","答：","答:","speech:"};
    private static boolean contains(String s,String[] words){s=s.toLowerCase(Locale.ROOT);for(String w:words)if(s.contains(w))return true;return false;}
    private static String prepare(String s,boolean emphasis){s=s.replaceAll("```[\\s\\S]*?```","").replaceAll("(?is)<(think|analysis|reasoning)>[\\s\\S]*?(?:</\\1>|$)","").replaceAll("https?://\\S+","");return emphasis?s.replaceAll("(?s)(?<!\\*)\\*(?!\\*)(.+?)(?<!\\*)\\*(?!\\*)",""):s;}
    private static boolean mental(String s){String[] v=s.toLowerCase(Locale.ROOT).trim().split("[。！？!?\\n；;]",-1);return contains(v[v.length-1],MENTAL);}
    private static String stripPunctuation(String s){return s.replaceAll("^[\\p{P}\\s]+|[\\p{P}\\s]+$","");}
    private static boolean narration(String s){for(String line:s.split("\\n",-1)){String v=stripPunctuation(line).toLowerCase(Locale.ROOT);if(v.matches("(?s)^(?:旁白|动作|心理活动|心理|内心独白|神态|外貌|身体描写|表情|舞台说明|narration|action|thoughts?)\\s*[:：].*"))return true;if(v.matches("^(?:她|他|恩雅|芬妮)[^。！？!?\\n]{0,80}(?:说|问|答)[:：]?$"))return true;if(Pattern.compile("^(?:她|他|少女|女孩|女人|角色|恩雅|芬妮|she\\b|he\\b)").matcher(v).find()&&contains(v,STAGES))return true;if(v.matches("^(?:却|又|轻声|柔声|低声|笑着)?(?:说|说道|回答|问道)\\s*[:：，,]?"))return true;}return false;}
    private record Quote(int start,int end,String text,String before){}
    private static List<Quote> quotes(String s){ArrayList<Quote> out=new ArrayList<>();int previous=0;Map<Character,Character> pairs=Map.of('“','”','「','」','『','』','"','"');for(int i=0;i<s.length();i++){Character close=pairs.get(s.charAt(i));if(close==null)continue;int scan=i+1,depth=1;for(;scan<s.length();scan++){char c=s.charAt(scan);if(c==close){if(--depth==0)break;}else if(s.charAt(i)!='"'&&c==s.charAt(i))depth++;}if(scan==s.length())break;out.add(new Quote(i,scan+1,s.substring(i+1,scan),s.substring(previous,i)));previous=scan+1;i=scan;}return out;}
    private static String stages(String s){StringBuilder out=new StringBuilder();Map<Character,Character> pairs=Map.of('（','）','(',')','【','】','[',']');for(int i=0;i<s.length();i++){Character close=pairs.get(s.charAt(i));if(close==null){out.append(s.charAt(i));continue;}ArrayDeque<Character> stack=new ArrayDeque<>();stack.push(close);int begin=i+1,scan=begin;for(;scan<s.length();scan++){char c=s.charAt(scan);if(pairs.containsKey(c)){stack.push(pairs.get(c));if(stack.size()>32)return out.toString();}else if(c==stack.peek()){stack.pop();if(stack.isEmpty())break;}}if(scan==s.length())break;String inner=s.substring(begin,scan).trim();if(s.charAt(i)=='（'||s.charAt(i)=='('){String tag=tag(inner);if(tag!=null)out.append(' ').append(explicit(inner.substring(tag.length()))).append(' ');else if(!mental(inner)&&!quotes(inner).isEmpty())out.append(' ').append(dialogue(inner)).append(' ');else if(!mental(inner)&&!inner.contains("想了想")&&!contains(inner,STAGES)&&Pattern.compile("^(?:我|你|我们|咱|你好|欢迎|嗯|唔|谢谢|对不起|别|请|おかえり|ただいま|うん|はい)").matcher(inner).find())out.append(' ').append(inner).append(' ');}i=scan;}return out.toString();}
    private static String tag(String s){for(String t:TAGS)if(s.toLowerCase(Locale.ROOT).startsWith(t))return t;return null;}
    private static String remainder(String s){ArrayList<String> lines=new ArrayList<>();for(String line:s.split("\\n",-1)){String v=line.trim();if(narration(v))continue;String t=tag(v);lines.add(t==null?v:v.substring(t.length()));}return String.join("\n",lines);}
    private static boolean words(String s){return s.codePoints().anyMatch(Character::isLetterOrDigit);}
    private static String finish(String s){s=s.replaceAll("[*_`#>]","").replaceAll("[ \\t]{2,}"," ").trim();return words(s)?s:"";}
    static String explicit(String s){return finish(stages(prepare(s,false)));}
    static String dialogue(String s){String text=stages(prepare(s,true));List<Quote> q=quotes(text);if(q.isEmpty())return finish(remainder(text));StringBuilder outside=new StringBuilder();int cursor=0;for(Quote v:q){outside.append(text,cursor,v.start);cursor=v.end;}outside.append(text.substring(cursor));if(!stripPunctuation(outside.toString()).isEmpty()&&!narration(outside.toString())&&q.stream().noneMatch(v->mental(v.before)))return finish(remainder(text));ArrayList<String> pieces=new ArrayList<>();int previous=0;for(Quote v:q){String prefix=remainder(text.substring(previous,v.start));if(words(prefix))pieces.add(prefix);if(!mental(v.before)){String line=explicit(v.text);if(words(line))pieces.add(line);}previous=v.end;}String tail=remainder(text.substring(previous));if(words(tail))pieces.add(tail);return finish(String.join("\n",pieces));}
    static List<String> sentences(String text){ArrayList<String> out=new ArrayList<>();StringBuilder part=new StringBuilder();for(int i=0;i<text.length();i++){char c=text.charAt(i);part.append(c);if("。！？!?\n".indexOf(c)>=0||part.length()>=32||part.length()>=18&&"，、,；;".indexOf(c)>=0){if(words(part.toString()))out.add(part.toString());part.setLength(0);}}if(words(part.toString()))out.add(part.toString());return out;}
}
